import {
  FocusEvent,
  Context,
  createContext,
  Dispatch,
  SetStateAction,
} from 'react';

type RadioGroupContextType = {
  /** The name of the radio group. */
  readonly name?: string;
  /** Whether the radio group is invalid. */
  readonly hasError?: boolean;
  /** The currently selected value. */
  readonly selectedValue: string | undefined | null;
  /** Whether the radio group is disabled. */
  readonly isDisabled?: boolean;
  setSelectedValue: Dispatch<SetStateAction<string>> | undefined;
  /** Handler that is called when the value of the group changes. */
  onChange?: (value: string, event?: FocusEvent<HTMLInputElement>) => void;
};

/** Context describing the state of a RadioGroup */
export const RadioGroupContext: Context<RadioGroupContextType> =
  createContext<RadioGroupContextType>({
    name: undefined,
    hasError: undefined,
    isDisabled: undefined,
    selectedValue: undefined,
    setSelectedValue: undefined,
    onChange: undefined,
  });
